using namespace std;

typedef long long ll;
typedef unsigned long long ull;

// Modular exponentiation: (base^exp) % mod
// Note: base and exp can be negative, but we handle them properly
ll mod_pow(ll base, ll exp, ll mod) {
    if (mod == 1) return 0;
    base %= mod;
    if (base < 0) base += mod;
    ll result = 1;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

// Compute sum_{i=0}^{t-1} (a + i) mod m
// = t*a + t*(t-1)/2 mod m
// We need to handle division by 2 carefully when m is even
ll sum_arithmetic(ll a, ll t, ll m) {
    if (t == 0) return 0;
    // sum = t*a + t*(t-1)/2
    // We compute this modulo m, but we need to handle the division by 2
    // If t is even, t/2 * (t-1) is integer
    // If t-1 is even, t * ((t-1)/2) is integer

    ll term1 = (t % m) * (a % m) % m;
    if (term1 < 0) term1 += m;

    ll term2;
    if (t % 2 == 0) {
        // t is even, so t/2 is integer
        ll half_t = t / 2;
        term2 = (half_t % m) * ((t - 1) % m) % m;
    } else {
        // t-1 is even, so (t-1)/2 is integer
        ll half_t_minus_1 = (t - 1) / 2;
        term2 = (t % m) * (half_t_minus_1 % m) % m;
    }
    if (term2 < 0) term2 += m;

    ll result = (term1 + term2) % m;
    if (result < 0) result += m;
    return result;
}

